@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<ThreadSummary> _threadSummaries = [];
    private int _activeChannelId;
    private Channel? _activeChannel;
    private bool _hasMoreMessages = true;
    private const int PageSize = 30;

    // Thread state
    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    private CancellationTokenSource _cts = new();

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages = [];
        _threadSummaries = [];
        _hasMoreMessages = true;
        CloseThreadInternal();

        var messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messages = messages;
        _hasMoreMessages = messages.Count == PageSize;

        // Build thread summaries from messages that have replies
        _threadSummaries = _messages
            .Where(m => m.ReplyToId is null)
            .Select(m => new ThreadSummary(m.Id, _messages.Count(r => r.ReplyToId == m.Id), m.SentAt))
            .Where(t => t.ReplyCount > 0)
            .ToList();

        await ChatService.MarkChannelReadAsync(channelId);

        // Update local unread count
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadMoreMessages()
    {
        if (!_hasMoreMessages || _activeChannel is null) return;

        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messages.Count, PageSize);
        if (older.Count < PageSize) _hasMoreMessages = false;
        _messages.InsertRange(0, older);
    }

    private async Task SendMessage(string content)
    {
        if (_activeChannel is null) return;
        var message = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _threadOpen = true;
    }

    private void CloseThread() => CloseThreadInternal();

    private void CloseThreadInternal()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null || _activeChannel is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannelId, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update thread summary count
        var idx = _threadSummaries.FindIndex(t => t.RootMessageId == _threadRootMessage.Id);
        if (idx >= 0)
        {
            _threadSummaries[idx] = _threadSummaries[idx] with { ReplyCount = _threadSummaries[idx].ReplyCount + 1, LastReplyAt = reply.SentAt };
        }
        else
        {
            _threadSummaries.Add(new ThreadSummary(_threadRootMessage.Id, 1, reply.SentAt));
        }
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update local state
        var msg = _messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
        }
    }

    public ValueTask DisposeAsync()
    {
        _cts.Cancel();
        _cts.Dispose();
        return ValueTask.CompletedTask;
    }
}

